#!/usr/bin/env python3
"""Chiang Mai #64 source rescue after manual rejection of weak autogenerated candidates.
Only exact authentic Creative Commons landscapes and official publisher photos.
No approval of hotel commercial rights; private protected preview only.
"""
import sys, pathlib,json,importlib.util,urllib.parse,re,hashlib
from PIL import Image,ImageDraw
spec=importlib.util.spec_from_file_location('source','scripts/collect-chiang-mai-media.py')
source=importlib.util.module_from_spec(spec);spec.loader.exec_module(source)
mfile=pathlib.Path('data/travel/chiangMaiMediaCandidates.json')
m=json.loads(mfile.read_text())
assert m['destination']=='chiang-mai'
scene_exact=[
 ('scene-1','Dusk Falling on the Stupa of Mount Suthep.jpg',"Doi Suthep · pagode dorée dans la lumière du soir","Doi Suthep's golden stupa in the evening light"),
 ('scene-2','Wat Chedi Luang, Stupa, Chiang Mai, Thailand.jpg',"Wat Chedi Luang · grand stupa historique de la vieille ville","Historic Wat Chedi Luang stupa in the Old City"),
 ('scene-3','Wat Phra Singh, Chiang Mai.jpg',"Wat Phra Singh · architecture sacrée de l'ancienne capitale Lanna","Wat Phra Singh temple in historic Chiang Mai"),
 ('scene-5','Watket.jpg',"Wat Ket Karam · temple historique du quartier Wat Gate","Wat Ket Karam temple in Chiang Mai's Wat Gate district"),
 ('scene-6','Ping River in Chiang Mai 1.jpg',"Rivière Ping, vue depuis le pont Chansom Memorial","Ping River from Chansom Memorial Bridge"),
 ('scene-7','Thai - rizière.jpg',"Rizières photographiées dans la région de Chiang Mai, pas une promesse de vue depuis l'hôtel","Rice fields photographed near Chiang Mai, not a guaranteed hotel view")
]
by_key={p['key']:p for p in m['destinationScenes']}
def commons_exact(row):
 key,title,fr,en=row
 args={'action':'query','format':'json','prop':'imageinfo','iiprop':'url|extmetadata|size',
       'iiurlwidth':1600,'titles':'File:'+title}
 d=source.request('https://commons.wikimedia.org/w/api.php?'+urllib.parse.urlencode(args)).json()
 pages=list(d['query']['pages'].values())
 if len(pages)!=1 or not pages[0].get('imageinfo'):raise ValueError('missing Commons File:'+title)
 data=pages[0]['imageinfo'][0];meta=data['extmetadata']
 license=source.txt(meta.get('LicenseShortName',{}).get('value',''))
 if not re.match(r'^(CC BY(?:-SA)? [234]\.0|CC0|Public domain)',license,re.I):
  raise ValueError('unsupported Commons license '+license+' '+title)
 u=data.get('thumburl') or data['url']
 loc='/images/travel/chiang-mai-premium/destination/'+key+'.webp'
 p=source.photo(u,pathlib.Path('public'+loc))
 return {**p,'key':key,'localPath':loc,'sourcePage':'https://commons.wikimedia.org/wiki/File:'+urllib.parse.quote(title.replace(' ','_'),safe='(),-._'),
  'downloadUrl':u,'credit':source.txt(meta.get('Artist',{}).get('value','')) or 'Wikimedia Commons creator',
  'license':license,'licenseUrl':meta.get('LicenseUrl',{}).get('value','https://creativecommons.org/licenses/'),
  'rightsEvidenceType':'wikimedia_license_metadata','commercialRightsCleared':True,
  'visuallyVerified':False,'status':'source_identified_pending_individual_visual_review',
  'frCaption':fr,'enCaption':en,'originalAlt':title,
  'visualReviewNote':'Sourced as exact Wikimedia File identity, awaiting updated contact-sheet review.'}
for p in scene_exact:
 new=commons_exact(p);by_key[p[0]]=new;print('EXACT_CITY',p[0],new['license'],new['bytes'],flush=True)
m['destinationScenes']=[by_key[k] for k in sorted(by_key)]
assert len(m['destinationScenes'])==9

publisher=[
 ('pillars','137 Pillars House Chiang Mai',[
  ('https://137pillarshotels.com/media/assets/facilities/01_The_HouseM.jpg','Historic 137 Pillars House timber residence'),
  ('https://137pillarshotels.com/media/assets/facilities/02_Lobby1M.jpg','Lobby at 137 Pillars House Chiang Mai'),
  ('https://137pillarshotels.com/media/assets/suites/09_Louis_Leonowens_Pool_Suites-BedM.jpg','Louis Leonowens Pool Suite bedroom')
 ],'https://137pillarshotels.com/en/media/images/'),
 ('four-seasons','Four Seasons Resort Chiang Mai',[
  ('https://www.fourseasonsthailand.com/press-kit/fs-chiang-mai/CHI_758.jpg','Four Seasons Chiang Mai press photograph CHI 758'),
  ('https://www.fourseasonsthailand.com/press-kit/fs-chiang-mai/CHI_1402.jpg','Four Seasons Chiang Mai press photograph CHI 1402'),
  ('https://www.fourseasonsthailand.com/press-kit/fs-chiang-mai/CHI_1555.jpg','Four Seasons Chiang Mai press photograph CHI 1555')
 ],'https://www.fourseasonsthailand.com/press-kit/fs-chiang-mai/')
]
hotels=[p for p in m['hotels'] if p['propertyKey'] not in ('pillars','four-seasons')]
for key,name,sources,origin in publisher:
 for i,(u,alt) in enumerate(sources,1):
  k='view-'+str(i);path='/images/travel/chiang-mai-premium/'+key+'/'+k+'.webp'
  binary=source.photo(u,pathlib.Path('public'+path))
  hotels.append({**binary,'key':k,'propertyKey':key,'property':name,'localPath':path,
   'sourcePage':origin,'downloadUrl':u,
   'credit':name+' official publisher; photographer licence not independently verified',
   'license':'Official hotel press media; commercial republication rights not independently confirmed.',
   'licenseUrl':origin,'rightsEvidenceType':'hotel_official_publisher_not_licensed',
   'commercialRightsCleared':False,'visuallyVerified':False,'status':'source_identified_pending_individual_visual_review',
   'originalAlt':alt,'frCaption':name+' · média officiel à vérifier individuellement',
   'enCaption':name+' · official publisher image pending individual visual check',
   'visualReviewNote':'Publisher identity confirmed from official media library; individual photo content requires manual review.'})
  print('OFFICIAL_HOTEL',key,k,binary['bytes'],flush=True)
m['hotels']=sorted(hotels,key=lambda x:(x['propertyKey'],x['key']))
assert len(m['destinationScenes'])==9 and len(m['hotels'])==12
fingerprints=[p['pixelFingerprint'] for p in m['destinationScenes']+m['hotels']]
assert len(set(fingerprints))==21,'Resized photo fingerprint collision: inspect duplicate imagery'
m['cityCount']=9;m['hotelCount']=12
m['visualQA']='PENDING_FINAL_21_IMAGE_VISUAL_REVIEW';m['publicUseApproved']=False
mfile.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
source.contact(m['destinationScenes']+m['hotels'])
report=json.loads(pathlib.Path('docs/travel-chiang-mai-acquisition-report.json').read_text())
report['cityCount']=9;report['hotelCount']=12;report['errors']=[]
report['sourceRescue']='Six CC landscapes from named Commons files and three official press photos per missing hotel; visual QA pending'
pathlib.Path('docs/travel-chiang-mai-acquisition-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print('CHIANG_MAI_RESCUED_21',len(m['destinationScenes']),len(m['hotels']))
